package io.forgeloop.control.integrations.github;
import static org.junit.jupiter.api.Assertions.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.util.HexFormat; import org.junit.jupiter.api.Test;
class GithubWebhookVerifierTest { @Test void validatesExactPayloadAndRejectsTampering() throws Exception {String body="{\"issue\":42}";String secret="test-secret";Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String signature="sha256="+HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));GithubWebhookVerifier verifier=new GithubWebhookVerifier();assertTrue(verifier.valid(secret,signature,body));assertFalse(verifier.valid(secret,signature,body+"x"));assertFalse(verifier.valid(secret,"sha256=bad",body));} }
